package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDeserializerFactory.BeanPropertyDefinition;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.impl.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.StdBeanProperty;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.AnnotationIntrospector;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_constructSettableProperty_TriageGen2Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanPropertyDefinition propDef;
    private JavaType propType0;
    private TypeFactory typeFactory;

    // A concrete subclass to expose the protected method for testing
    private static class TestableBeanDeserializerFactory extends BeanDeserializerFactory {
        public TestableBeanDeserializerFactory(DeserializerFactoryConfig config) {
            super(config);
        }

        @Override
        public SettableBeanProperty constructSettableProperty(DeserializationContext ctxt,
                                                              BeanDescription beanDesc,
                                                              BeanPropertyDefinition propDef,
                                                              JavaType propType0) throws JsonMappingException {
            return super.constructSettableProperty(ctxt, beanDesc, propDef, propType0);
        }

        // Overriding to prevent actual resolution logic from failing due to missing internal state
        @Override
        protected JavaType resolveType(DeserializationContext ctxt, BeanDescription beanDesc, JavaType propType0, AnnotatedMember mutator) {
            return propType0;
        }

        @Override
        protected JsonDeserializer<Object> findDeserializerFromAnnotation(DeserializationContext ctxt, AnnotatedMember mutator) {
            return null;
        }

        @Override
        protected JavaType modifyTypeByAnnotation(DeserializationContext ctxt, AnnotatedMember mutator, JavaType type) {
            return type;
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBeanDeserializerFactory(null);
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        propDef = mock(BeanPropertyDefinition.class);
        typeFactory = TypeFactory.defaultInstance();
        propType0 = typeFactory.constructType(String.class);

        when(beanDesc.getClassAnnotations()).thenReturn(null);
    }

    @Test
    public void testConstructSettableProperty_MethodProperty() throws Exception {
        // Setup for AnnotatedMethod (Setter)
        DummyBean dummy = new DummyBean();
        Field setterField = DummyBean.class.getDeclaredMethod("setTestName", String.class);
        AnnotatedMethod annotatedMethod = mock(AnnotatedMethod.class);

        // Mocking internal mechanics of AnnotatedMember/Method
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedMethod);
        when(propDef.getFullName()).thenReturn("testName");
        when(propDef.getWrapperName()).thenReturn(null);
        when(propDef.getMetadata()).thenReturn(null);
        when(propDef.findReferenceType()).thenReturn(null);
        when(propDef.findObjectIdInfo()).thenReturn(null);

        when(ctxt.canOverrideAccessModifiers()).thenReturn(true);
        when(ctxt.isEnabled(MapperFeature.OVERRIDE_PUBLIC_ACCESS_MODIFIERS)).thenReturn(true);

        SettableBeanProperty result = factory.constructSettableProperty(ctxt, beanDesc, propDef, propType0);

        assertNotNull(result);
        assertTrue(result instanceof MethodProperty);
        verify(annotatedMethod).fixAccess(true);
    }

    @Test
    public void testConstructSettableProperty_FieldProperty() throws Exception {
        // Setup for AnnotatedField
        AnnotatedField annotatedField = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedField);
        when(propDef.getFullName()).thenReturn("testField");
        when(propDef.getWrapperName()).thenReturn(null);
        when(propDef.getMetadata()).thenReturn(null);
        when(propDef.findReferenceType()).thenReturn(null);
        when(propDef.findObjectIdInfo()).thenReturn(null);

        when(ctxt.canOverrideAccessModifiers()).thenReturn(false);

        SettableBeanProperty result = factory.constructSettableProperty(ctxt, beanDesc, propDef, propType0);

        assertNotNull(result);
        assertTrue(result instanceof FieldProperty);
    }

    @Test
    public void testConstructSettableProperty_WithTypeChange() throws Exception {
        // This test targets the "if (type != propType0)" branch
        TestableBeanDeserializerFactory spyFactory = spy(new TestableBeanDeserializerFactory(null));

        AnnotatedField annotatedField = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedField);
        when(propDef.getFullName()).thenReturn("testField");

        JavaType newType = typeFactory.constructType(Integer.class);

        // We need to override resolveType in the spy for this specific test
        doReturn(newType).when(spyFactory).resolveType(any(), any(), any(), any());

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType0);

        assertNotNull(result);
        assertEquals(newType, result.getType());
    }

    @Test
    public void testConstructSettableProperty_WithDeserializerAnnotation() throws Exception {
        AnnotatedField annotatedField = mock(AnnotatedField.class);
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);

        when(propDef.getNonConstructorMutator()).thenReturn(annotatedField);
        when(propDef.getFullName()).thenReturn("testField");

        // Mock the factory to return a deserializer
        TestableBeanDeserializerFactory spyFactory = spy(new TestableBeanDeserializerFactory(null));
        doReturn(mockDeser).when(spyFactory).findDeserializerFromAnnotation(any(), any());

        SettableBeanProperty result = spyFactory.constructSettableProperty(ctxt, beanDesc, propDef, propType0);

        assertNotNull(result);
        assertEquals(mockDeser, result.getValueDeserializer());
    }

    @Test
    public void testConstructSettableProperty_WithManagedReference() throws Exception {
        AnnotatedField annotatedField = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedField);
        when(propDef.getFullName()).thenReturn("testField");

        AnnotationIntrospector.ReferenceProperty ref = mock(AnnotationIntrospector.ReferenceProperty.class);
        when(ref.isManagedReference()).thenReturn(true);
        when(ref.getName()).thenReturn("myRef");
        when(propDef.findReferenceType()).thenReturn(ref);

        SettableBeanProperty result = factory.constructSettableProperty(ctxt, beanDesc, propDef, propType0);

        assertNotNull(result);
        assertEquals("myRef", result.getManagedReferenceName());
    }

    @Test
    public void testConstructSettableProperty_WithObjectIdInfo() throws Exception {
        AnnotatedField annotatedField = mock(AnnotatedField.class);
        when(propDef.getNonConstructorMutator()).thenReturn(annotatedField);
        when(propDef.getFullName()).thenReturn("testField");

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(propDef.findObjectIdInfo()).thenReturn(objectIdInfo);

        SettableBeanProperty result = factory.constructSettableProperty(ctxt, beanDesc, propDef, propType0);

        assertNotNull(result);
        assertEquals(objectIdInfo, result.getObjectIdInfo());
    }

    // Helper classes for mocking
    public static class DummyBean {
        private String testName;
        public void setTestName(String testName) { this.testName = testName; }
    }

    // Mocking Jackson's internal annotated classes which are hard to instantiate
    private interface AnnotatedField extends AnnotatedMember {}
    private interface AnnotatedMethod extends AnnotatedMember {}
    private interface AnnotatedMember extends com.fasterxml.jackson.databind.introspect.Annotated {}
}

// Since the source code uses internal Jackson classes that are difficult to mock without 
// actual reflection or heavy Mockito usage, we assume the presence of the following 
// mocks/interfaces if they are not easily accessible in the test classpath.
// In a real Jackson environment, these would be provided by the library.
